/* Hazard presentation. Fire uses a small number of animated, clustered
 * billboards with rising smoke volumes; field values remain in fire-core.js. */
(() => {
  'use strict';
  const L = window.IndoorLab;
  function fireTexture() {
    const c = document.createElement('canvas'); c.width = c.height = 256; const x = c.getContext('2d');
    const g = x.createRadialGradient(128, 176, 2, 128, 132, 132); g.addColorStop(0, '#fffdf0'); g.addColorStop(.11, '#fff1a2'); g.addColorStop(.3, '#ffbf37'); g.addColorStop(.57, '#ff5b1c'); g.addColorStop(.78, 'rgba(190,24,0,.45)'); g.addColorStop(1, 'rgba(30,8,0,0)'); x.fillStyle = g; x.fillRect(0, 0, 256, 256);
    x.globalCompositeOperation = 'destination-out'; for (let i = 0; i < 13; i++) { const xx = 30 + ((i * 67) % 195), yy = 58 + ((i * 43) % 106); x.beginPath(); x.ellipse(xx, yy, 14 + (i % 5) * 4, 35 + (i % 4) * 8, ((i % 3) - 1) * .35, 0, Math.PI * 2); x.fill(); } return new THREE.CanvasTexture(c);
  }
  function smokeTexture() { const c = document.createElement('canvas'); c.width = c.height = 256; const x = c.getContext('2d'), g = x.createRadialGradient(128, 128, 8, 128, 128, 130); g.addColorStop(0, 'rgba(42,34,31,.62)'); g.addColorStop(.3, 'rgba(72,65,63,.46)'); g.addColorStop(.67, 'rgba(104,100,100,.23)'); g.addColorStop(1, 'rgba(150,150,150,0)'); x.fillStyle = g; x.fillRect(0, 0, 256, 256); return new THREE.CanvasTexture(c); }
  function seed2(i) { const x = Math.sin(i * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); }
  class DisasterRenderer {
    constructor(view) { this.view = view; this.group = new THREE.Group(); this.group.userData.noAO = true; view.scene.add(this.group); this.flameTexture = fireTexture(); this.smokeTexture = smokeTexture(); this.hazard = null; this.type = 'none'; this.flames = []; this.smokes = []; this.embers = []; this.debris = []; this.lights = []; this.clock = 0; this._clusterVersion = -1; this._clusterCache = []; }
    clear() { for (const o of [...this.flames, ...this.smokes, ...this.embers, ...this.debris, ...this.lights]) { this.group.remove(o); o.geometry?.dispose(); o.material?.dispose(); } this.flames = []; this.smokes = []; this.embers = []; this.debris = []; this.lights = []; this.hazard = null; this.type = 'none'; this.clock = 0; this._clusterVersion = -1; this._clusterCache = []; }
    set(hazard, type = 'none') { this.clear(); this.hazard = hazard; this.type = type; }
    makeSprite(map, blend, opacity) { const s = new THREE.Sprite(new THREE.SpriteMaterial({ map, transparent: true, opacity, depthWrite: false, blending: blend })); this.group.add(s); return s; }
    makeLight() { const l = new THREE.PointLight('#ff6a1c', 0, 7.5, 1.8); this.group.add(l); this.lights.push(l); return l; }
    update() { if (!this.hazard) return; this.clock = this.hazard.time || this.clock; if (this.type === 'fire') this.updateFire(); else if (this.type === 'earthquake') this.updateQuake(); }
    _clusters() { const h = this.hazard, g = this.view.grid, version = h.fieldVersion === undefined ? h.time : h.fieldVersion; if (version === this._clusterVersion) return this._clusterCache; const cells = []; for (let i = 0; i < g.size; i++) { const w = h.flame[i]; if (w <= .05) continue; let at = cells.length; while (at && cells[at - 1][1] < w) at--; if (at < 18) cells.splice(at, 0, [i, w]); if (cells.length > 18) cells.pop(); } const out = [], used = new Uint8Array(g.size), radius = Math.max(1, Math.ceil(1.0 / g.cell)); for (const [i, v] of cells) { if (out.length >= 10 || used[i]) continue; const p = g.point(i), c0 = i % g.cols, r0 = Math.floor(i / g.cols); let sx = p.x * v, sz = p.z * v, sw = v, count = 0; for (let r = Math.max(0, r0 - radius); r <= Math.min(g.rows - 1, r0 + radius); r++) for (let c = Math.max(0, c0 - radius); c <= Math.min(g.cols - 1, c0 + radius); c++) { const j = r * g.cols + c, w = h.flame[j]; if (!w || used[j]) continue; const q = g.point(j); if (Math.hypot(q.x - p.x, q.z - p.z) < Math.max(g.cell * 2.4, .9)) { used[j] = 1; sx += q.x * w; sz += q.z * w; sw += w; if (++count >= 40) break; } } out.push({ x: sx / sw, z: sz / sw, strength: Math.min(1, sw / Math.max(1, count * .4)), count }); } this._clusterVersion = version; this._clusterCache = out; return out; }
    updateFire() { const h = this.hazard, g = this.view.grid, clusters = this._clusters(); while (this.flames.length < clusters.length) this.flames.push(this.makeSprite(this.flameTexture, THREE.NormalBlending, .88)); while (this.smokes.length < Math.min(24, clusters.length * 2)) this.smokes.push(this.makeSprite(this.smokeTexture, THREE.NormalBlending, .36)); while (this.embers.length < Math.min(30, clusters.length * 2)) { const s = this.makeSprite(this.flameTexture, THREE.AdditiveBlending, .62); s.userData.seed = this.embers.length + 11; this.embers.push(s); } while (this.lights.length < Math.min(8, clusters.length)) this.makeLight(); for (let i = 0; i < this.flames.length; i++) { const s = this.flames[i], c = clusters[i]; if (!c) { s.visible = false; continue; } s.visible = true; const wave = .86 + .16 * Math.sin(this.clock * 7.5 + i * 1.71) + .08 * Math.sin(this.clock * 13 + i * 3.2), height = (.92 + c.strength * 1.85) * wave; s.position.set(c.x, .18 + height * .44, c.z); s.scale.set(.72 + c.strength * 1.0, height * 1.45, 1); s.material.opacity = .44 + c.strength * .68; } for (let i = 0; i < this.smokes.length; i++) { const s = this.smokes[i], c = clusters[Math.floor(i / 2)]; if (!c) { s.visible = false; continue; } const phase = seed2(i + 10), rise = (this.clock * (.11 + phase * .08) + phase * 2) % 2.8, curl = Math.sin(this.clock * .7 + i * 1.3) * (.18 + rise * .12), ci = g.index(c.x, c.z), floorSmoke = ci >= 0 ? h.smoke[ci] : 0, ceilingSmoke = ci >= 0 ? (h.ceilingSmoke?.[ci] || 0) : 0, density = Math.min(1, floorSmoke * 1.35 + ceilingSmoke * 1.4 + c.strength * .1); s.visible = density > .02; s.position.set(c.x + curl, 1.0 + rise, c.z + Math.cos(this.clock * .8 + i) * .12); const size = .5 + density * 2.1 + rise * .28; s.scale.set(size * 1.18, size, size); s.material.opacity = .1 + density * .4; } for (let i = 0; i < this.embers.length; i++) { const s = this.embers[i], c = clusters[i % Math.max(1, clusters.length)]; if (!c) { s.visible = false; continue; } const phase = seed2(i + 80), t = (this.clock * (.6 + phase) + phase * 2) % 1.4; s.visible = t < .9; s.position.set(c.x + Math.sin(this.clock * 2 + i) * .4, .2 + t * 1.8, c.z + Math.cos(this.clock * 2.3 + i) * .4); const q = .04 + .045 * (1 - t); s.scale.set(q, q * 1.4, q); s.material.opacity = .35 * (1 - t); } for (let i = 0; i < this.lights.length; i++) { const l = this.lights[i], c = clusters[i]; if (!c) { l.visible = false; continue; } l.visible = true; l.position.set(c.x, .4, c.z); l.intensity = 1.6 + c.strength * 5.2 + Math.sin(this.clock * 8 + i) * .55; } }
    updateQuake() { const q = this.hazard; q.physics?.syncVisuals?.(); for (const event of q.events || []) { if (this.debris.some(d => d.userData.eventTime === event.time && d.userData.eventId === event.id)) continue; const mesh = new THREE.Mesh(new THREE.BoxGeometry(.38, .2, .38), new THREE.MeshStandardMaterial({ color: '#8b6e5a', roughness: .85 })); mesh.position.set(event.x, 2.2, event.z); mesh.userData = { eventTime: event.time, eventId: event.id, vy: 0 }; this.group.add(mesh); this.debris.push(mesh); } for (const d of this.debris) { if (d.position.y > .18) { d.userData.vy -= .18; d.position.y = Math.max(.18, d.position.y + d.userData.vy); d.rotation.x += .018; d.rotation.z += .013; } } }
    dispose() { this.clear(); this.flameTexture.dispose(); this.smokeTexture.dispose(); this.view.scene.remove(this.group); }
  }
  L.DisasterRenderer = DisasterRenderer;
})();


